UPDATE runtime_operations SET status='queued',max_attempts=max_attempts+1,available_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER),worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,cache_bypassed=1,planned_artifact_count=NULL,delivered_artifact_count=0,delivered_message_id=NULL,delivery_started_at=NULL,progress_percent=NULL,progress_stage=NULL,updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE id=?1 AND attempt=?2 AND lease_token=?3 AND worker_id=?4 AND status='delivering' AND lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER) AND EXISTS(SELECT 1 FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND ordinal=0 AND status='rejected');